'use strict';
const WORDS=[{id:'A1',word:'早操',pinyin:'zǎo cāo',meaning:'早上做的體操。'},{id:'A2',word:'陽光',pinyin:'yáng guāng',meaning:'太陽照下來的光。'},{id:'A3',word:'鳥兒',pinyin:'niǎor',meaning:'會飛的小動物。'},{id:'A4',word:'花朵',pinyin:'huā duǒ',meaning:'一朵一朵的花。'},{id:'A5',word:'學生',pinyin:'xué sheng',meaning:'在學校學習的人。'},{id:'A6',word:'跑',pinyin:'pǎo',meaning:'比走路更快的動作。'}];
const STEPS=['看字聽讀','抄寫兩次','遮字聽寫','自己核對'];const KEY='genevieve-words-A-v1';let index=0,step=0,marks={},storageOK=true,activeAudio=null;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved)){marks=saved.marks||{};index=Number.isInteger(saved.index)&&saved.index>=0&&saved.index<6?saved.index:0;step=Number.isInteger(saved.step)&&saved.step>=0&&saved.step<4?saved.step:0;}}catch{storageOK=false;}
const $=s=>document.querySelector(s);function stop(){if(activeAudio){activeAudio.pause();activeAudio.currentTime=0;activeAudio=null;}}
function save(){try{localStorage.setItem(KEY,JSON.stringify({marks,index,step}));}catch{storageOK=false;}$('#saved').textContent=storageOK?'進度只儲存在這部裝置':'這個瀏覽器未能保存進度，仍可繼續練習';}
function render(){stop();const w=WORDS[index],hide=step===2;$('#qid').textContent=w.id;$('#phase').textContent=STEPS[step];$('#word').textContent=hide?'聽一聽':w.word;$('#word').classList.toggle('hiddenword',hide);$('#word').setAttribute('aria-label','播放這一題的普通話讀音');$('#pinyin').textContent=hide?'':w.pinyin;$('#meaning').textContent=hide?'先聽讀音，寫完再核對。':w.meaning;$('#location').textContent=w.id+'｜'+(['先找到上半頁示範字','上半頁「抄寫一、抄寫二」','下半頁「聽寫」格','下半頁「聽寫」格'][step]);$('#instruction').textContent=['撳播放，跟着讀一讀，看看這個詞。','每格一個字，把完整詞語寫兩次。','沿中線摺埋上半頁，遮住示範字。撳播放再落筆。','睇返答案，對一對自己寫的每個字。'][step];$('#audioStatus').textContent='撳播放，可以再聽一次。';$('#marking').hidden=step!==3;$('#next').textContent=['去抄寫 →','去聽寫 →','寫好喇，核對 →',index===5?'完成練習 ✓':'下一題 →'][step];$('#previous').disabled=index===0;$('#counter').textContent=`練習 A · 第 ${index+1} / 6 題`;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.step)===step);b.setAttribute('aria-current',Number(b.dataset.step)===step?'step':'false');});const nav=$('#wordnav');nav.replaceChildren();WORDS.forEach((item,i)=>{const b=document.createElement('button');b.className=i===index?'active':'';b.setAttribute('aria-label','轉到 '+item.id);b.innerHTML=`<span class="num">${item.id}</span><span>${hide?'第 '+(i+1)+' 題':item.word}</span><span class="badge">${marks[item.id]==='known'?'✓':marks[item.id]==='again'?'↺':'·'}</span>`;b.onclick=()=>{index=i;render();};nav.append(b);});const count=WORDS.filter(w=>marks[w.id]==='known').length;$('#progressLabel').textContent=`${count} / 6 個已掌握`;$('#progress').style.width=count/6*100+'%';$('#done').hidden=true;save();}
function play(slow=false){stop();const a=new Audio(`audio/${WORDS[index].id}.mp3`);activeAudio=a;a.playbackRate=slow?.75:1;a.preservesPitch=true;$('#audioStatus').textContent=slow?'正在慢慢讀普通話…':'正在播放普通話…';a.onended=()=>{$('#audioStatus').textContent='聽完喇。想再聽，可以再撳播放。';};a.onerror=()=>{$('#audioStatus').textContent='音檔未能播放，請檢查連線後重試。';};a.play().catch(()=>{$('#audioStatus').textContent='未能播放，請再撳一次，並檢查媒體音量。';});}
$('#play').onclick=()=>play();$('#slow').onclick=()=>play(true);$('#word').onclick=()=>play();document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render();});$('#previous').onclick=()=>{if(index>0){index--;step=0;render();}};$('#next').onclick=()=>{if(step<3){step++;render();}else if(index<5){index++;step=0;render();}else{stop();$('#done').hidden=false;$('#done').scrollIntoView({behavior:'smooth',block:'nearest'});}};
function mark(value){marks[WORDS[index].id]=value;render();$('#audioStatus').textContent=value==='known'?'已記低：我識寫喇。可以去下一題。':'已記低：再練一次。可以重播，或者去下一題。';}$('#known').onclick=()=>mark('known');$('#again').onclick=()=>mark('again');$('#reviewButton').onclick=()=>{const i=WORDS.findIndex(w=>marks[w.id]==='again');if(i>=0){index=i;step=0;render();}else{$('#audioStatus').textContent='未有標記「再練」的字，可以由 A1 開始。';}};$('#helpButton').onclick=()=>{$('#help').hidden=!$('#help').hidden;$('#helpButton').setAttribute('aria-expanded',String(!$('#help').hidden));};$('#reset').onclick=()=>{if(confirm('清除這組六個字的學習進度？')){marks={};index=0;step=0;render();}};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});render();
